import React, { useState } from "react";
import axios from "axios";

export default function AdminPage() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [msg, setMsg] = useState("");
  const [token, setToken] = useState("");
  const [users, setUsers] = useState([]);

  const login = async (e) => {
    e.preventDefault();
    setMsg("");
    try {
      const { data } = await axios.post("/api/admin/login", { email, password });
      setToken(data.token);
      // store token for admin panel and also as main roomly token so dashboard recognizes admin
      localStorage.setItem("roomly_admin_token", data.token);
      localStorage.setItem("roomly_token", data.token);
      axios.defaults.headers.common["Authorization"] = `Bearer ${data.token}`;
      setMsg("Logged in as admin.");
      // redirect to dashboard to use existing admin UI
      window.location.href = "/dashboard";
    } catch (err) {
      setMsg(err.response?.data?.message || "Login failed.");
    }
  };

  const fetchUsers = async () => {
    try {
      const { data } = await axios.get("/api/users");
      setUsers(data.users || []);
    } catch (err) {
      setMsg(err.response?.data?.message || "Could not load users.");
    }
  };

  const promote = async (id) => {
    try {
      await axios.patch(`/api/users/${id}/promote`);
      setMsg("User promoted to admin.");
      fetchUsers();
    } catch (err) {
      setMsg(err.response?.data?.message || "Could not promote user.");
    }
  };

  const demote = async (id) => {
    try {
      await axios.patch(`/api/users/${id}/demote`);
      setMsg("User demoted to guest.");
      fetchUsers();
    } catch (err) {
      setMsg(err.response?.data?.message || "Could not demote user.");
    }
  };

  return (
    <div style={{ padding: 40 }}>
      <h2>Admin panel</h2>
      <form onSubmit={login} style={{ display: "flex", gap: 8, marginBottom: 12 }}>
        <input placeholder="email" value={email} onChange={e => setEmail(e.target.value)} />
        <input placeholder="password" type="password" value={password} onChange={e => setPassword(e.target.value)} />
        <button type="submit">Sign in</button>
      </form>
      <div style={{ color: "red", marginBottom: 12 }}>{msg}</div>
      <div style={{ display: "flex", gap: 8, marginBottom: 12 }}>
        <button onClick={fetchUsers}>Load users</button>
      </div>
      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead>
          <tr>
            <th>Name</th>
            <th>Email</th>
            <th>Role</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {users.map(u => (
            <tr key={u._id}>
              <td>{u.first_name} {u.last_name}</td>
              <td>{u.email}</td>
              <td>{u.role}</td>
              <td>
                {u.role !== 'admin' ? (
                  <button onClick={() => promote(u._id)}>Promote</button>
                ) : (
                  <button onClick={() => demote(u._id)}>Demote</button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
